using System.Collections;
using System.Collections.Generic;
using System.Reflection;
using UnityEngine;

public class SawmillProcessingLine : MonoBehaviour
{
    LumberPrototypeBootstrap game; Transform player,intake,sawPoint,output,blade,exitPoint;
    readonly Queue<GameObject> waiting=new Queue<GameObject>(); readonly List<GameObject> finished=new List<GameObject>();
    FieldInfo carriedField,boardsField,sawmillField,playerField; MethodInfo refreshBackpack; bool processing;
    readonly Color orange=new Color(.95f,.36f,.06f), dark=new Color(.10f,.12f,.13f), steel=new Color(.34f,.38f,.40f), wood=new Color(.72f,.43f,.20f), board=new Color(.88f,.67f,.38f);
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Install(){new GameObject("Sawmill Processing Line").AddComponent<SawmillProcessingLine>();}
    IEnumerator Start(){for(int i=0;i<600&&game==null;i++){game=FindFirstObjectByType<LumberPrototypeBootstrap>();if(game==null){yield return null;continue;}var t=typeof(LumberPrototypeBootstrap);carriedField=t.GetField("carriedLogs",BindingFlags.Instance|BindingFlags.NonPublic);boardsField=t.GetField("boards",BindingFlags.Instance|BindingFlags.NonPublic);sawmillField=t.GetField("sawmill",BindingFlags.Instance|BindingFlags.NonPublic);playerField=t.GetField("player",BindingFlags.Instance|BindingFlags.NonPublic);refreshBackpack=t.GetMethod("RefreshBackpack",BindingFlags.Instance|BindingFlags.NonPublic);player=playerField!=null?(Transform)playerField.GetValue(game):null;}if(game==null||player==null)yield break;BuildStation();var dummy=new GameObject("Legacy Sawmill Trigger Disabled");dummy.transform.position=new Vector3(9999,0,9999);if(sawmillField!=null)sawmillField.SetValue(game,dummy.transform);}
    void Update(){if(blade!=null&&processing)blade.Rotate(Vector3.forward,300f*Time.deltaTime,Space.Self);if(game==null||player==null||intake==null)return;int carried=(int)carriedField.GetValue(game);Vector3 d=player.position-intake.position;d.y=0;if(carried>0&&d.sqrMagnitude<5.2f){Deposit(carried);carriedField.SetValue(game,0);refreshBackpack?.Invoke(game,null);}if(!processing&&waiting.Count>0)StartCoroutine(ProcessNext());}
    void Deposit(int count){for(int i=0;i<count;i++)waiting.Enqueue(MakeLog("Raw Log"));RestackWaiting();}
    IEnumerator ProcessNext(){processing=true;GameObject log=waiting.Dequeue();if(log==null){processing=false;yield break;}RestackWaiting();Vector3 a=log.transform.position,b=sawPoint.position+Vector3.up*.11f;yield return Move(log,a,b,2.8f);yield return new WaitForSeconds(.38f);Destroy(log);yield return null;RestackWaiting();yield return new WaitForSeconds(.18f);for(int n=0;n<2;n++){GameObject plank=MakeMovingBoard();Vector3 from=exitPoint.position+new Vector3(0,.08f,n*.13f-.065f);Vector3 to=OutputStackPosition(finished.Count);plank.transform.position=from;yield return Move(plank,from,to,1.9f);finished.Add(plank);}int boards=(int)boardsField.GetValue(game);boardsField.SetValue(game,boards+2);yield return new WaitForSeconds(.4f);processing=false;}
    IEnumerator Move(GameObject g,Vector3 a,Vector3 b,float seconds){float t=0;while(t<1&&g!=null){t+=Time.deltaTime/seconds;g.transform.position=Vector3.Lerp(a,b,Mathf.SmoothStep(0,1,t));yield return null;}}
    GameObject MakeMovingBoard(){var b=GameObject.CreatePrimitive(PrimitiveType.Cube);b.name="Finished Board";b.transform.localScale=new Vector3(.13f,.04f,.38f);Paint(b,board);Destroy(b.GetComponent<Collider>());return b;}
    Vector3 OutputStackPosition(int i){i%=42;int row=i/7,col=i%7;return output.position+new Vector3((col-3f)*.15f,.05f+row*.065f,0);}
    void RestackWaiting(){int i=0;foreach(var log in waiting){if(log==null)continue;int group=i/15,n=i%15,layer,slot,width;if(n<5){layer=0;slot=n;width=5;}else if(n<9){layer=1;slot=n-5;width=4;}else if(n<12){layer=2;slot=n-9;width=3;}else if(n<14){layer=3;slot=n-12;width=2;}else{layer=4;slot=0;width=1;}float x=(slot-(width-1)*.5f)*.18f;float z=(group-1)*.42f;log.transform.position=intake.position+new Vector3(x,.09f+layer*.15f,z);i++;}}
    void BuildStation(){var root=new GameObject("Cartoon Lumber Processing Line");root.transform.position=new Vector3(9.2f,0,3.2f);root.transform.localScale=Vector3.one*.78f;intake=Zone(root.transform,"RAW STORAGE",new Vector3(-4.65f,.025f,0),new Vector3(2.15f,.05f,2.15f));output=Zone(root.transform,"BOARD STORAGE",new Vector3(4.65f,.025f,0),new Vector3(2.15f,.05f,2.15f));AddBox(root.transform,"Black Feed Conveyor",new Vector3(-1.65f,.48f,0),new Vector3(2.45f,.15f,1.08f),dark);AddBox(root.transform,"Black Output Conveyor",new Vector3(1.65f,.48f,0),new Vector3(2.45f,.15f,1.08f),dark);for(int side=-1;side<=1;side+=2){Leg(root.transform,new Vector3(-1.65f,.23f,side*.41f));Leg(root.transform,new Vector3(1.65f,.23f,side*.41f));AddBox(root.transform,"Conveyor Rail",new Vector3(-1.65f,.62f,side*.50f),new Vector3(2.55f,.11f,.09f),steel);AddBox(root.transform,"Conveyor Rail",new Vector3(1.65f,.62f,side*.50f),new Vector3(2.55f,.11f,.09f),steel);}AddBox(root.transform,"Saw Body",new Vector3(0,.48f,0),new Vector3(1.60f,.76f,1.42f),steel);AddBox(root.transform,"Orange Left Tower",new Vector3(-.77f,.80f,0),new Vector3(.24f,1.12f,1.54f),orange);AddBox(root.transform,"Orange Right Tower",new Vector3(.77f,.80f,0),new Vector3(.24f,1.12f,1.54f),orange);AddBox(root.transform,"Orange Top Guard",new Vector3(0,1.34f,0),new Vector3(1.72f,.23f,1.54f),orange);var wheel=GameObject.CreatePrimitive(PrimitiveType.Cylinder);wheel.name="Circular Blade";wheel.transform.SetParent(root.transform);wheel.transform.localPosition=new Vector3(0,.96f,0);wheel.transform.localScale=new Vector3(.70f,.05f,.70f);wheel.transform.localRotation=Quaternion.Euler(90,0,0);Paint(wheel,new Color(.76f,.78f,.79f));Destroy(wheel.GetComponent<Collider>());blade=wheel.transform;AddBox(root.transform,"Motor",new Vector3(0,.34f,-.94f),new Vector3(.78f,.56f,.48f),dark);sawPoint=new GameObject("Saw Feed Point").transform;sawPoint.SetParent(root.transform);sawPoint.localPosition=new Vector3(0,.62f,0);exitPoint=new GameObject("Board Exit Point").transform;exitPoint.SetParent(root.transform);exitPoint.localPosition=new Vector3(.92f,.62f,0);}
    void Leg(Transform p,Vector3 pos){AddBox(p,"Conveyor Leg",pos,new Vector3(.13f,.46f,.13f),steel);}Transform Zone(Transform p,string n,Vector3 pos,Vector3 scale){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p);g.transform.localPosition=pos;g.transform.localScale=scale;Paint(g,new Color(.66f,.55f,.36f));Destroy(g.GetComponent<Collider>());for(int side=-1;side<=1;side+=2){AddBox(p,n+" Border",pos+new Vector3(0,.045f,side*scale.z*.5f),new Vector3(scale.x,.07f,.07f),new Color(.92f,.88f,.72f));AddBox(p,n+" Border",pos+new Vector3(side*scale.x*.5f,.045f,0),new Vector3(.07f,.07f,scale.z),new Color(.92f,.88f,.72f));}return g.transform;}
    void AddBox(Transform p,string n,Vector3 pos,Vector3 scale,Color c){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p);g.transform.localPosition=pos;g.transform.localScale=scale;Paint(g,c);Destroy(g.GetComponent<Collider>());}GameObject MakeLog(string n){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=n;g.transform.localScale=new Vector3(.10f,.24f,.10f);g.transform.rotation=Quaternion.Euler(0,0,90);Paint(g,wood);Destroy(g.GetComponent<Collider>());return g;}
    Material Mat(Color c){Shader s=Shader.Find("Universal Render Pipeline/Lit");if(s==null)s=Shader.Find("Sprites/Default");var m=new Material(s);m.color=c;return m;}void Paint(GameObject o,Color c){var r=o.GetComponent<Renderer>();if(r!=null)r.material=Mat(c);}
}
